from typing import Tuple

def energy(a: int, b: int, c: int, n: int) -> int:
    return (a*a + b*b - c*c)**2 + (a*b - n)**2

def spectrum(triple: Tuple[int, int, int], radius: int = 5) -> list[tuple[int, int]]:
    a, b, c = triple
    center = a*b
    return [(n, energy(a, b, c, n)) for n in range(center-radius, center+radius+1)]

if __name__ == "__main__":
    values = spectrum((5, 12, 13))
    for n, value in values:
        print(f"N={n:3d}  E={value:3d}")
    assert min(values, key=lambda pair: pair[1]) == (60, 0)

from typing import Tuple

Triple = Tuple[int, int, int]

def energy(t: Triple, n: int) -> int:
    a, b, c = t
    return (a*a + b*b - c*c)**2 + (a*b - n)**2

def second_difference(t: Triple, n: int, h: int) -> int:
    return energy(t, n+h) + energy(t, n-h) - 2*energy(t, n)

if __name__ == "__main__":
    triples = [(3, 4, 5), (2, 3, 4), (-5, 12, 13)]
    for t in triples:
        for n in range(-4, 5):
            for h in range(-3, 4):
                assert second_difference(t, n, h) == 2*h*h
    print("The identity Δ²_h E = 2h² holds on the entire test grid.")

