from typing import Iterable, Optional, Tuple

Triple = Tuple[int, int, int]

def energy(t: Triple, target: int) -> int:
    a, b, c = t
    return (a*a + b*b - c*c)**2 + (a*b-target)**2

def best_candidate(candidates: Iterable[Triple], target: int) -> Optional[Tuple[Triple, int]]:
    """Return a least-energy candidate from a finite iterable."""
    best: Optional[Tuple[Triple, int]] = None
    for triple in candidates:
        value = energy(triple, target)
        if best is None or value < best[1]:
            best = (triple, value)
        if value == 0:
            break
    return best

